1	#include "Variables.glsl.c"
2	
3	struct Specimen {
4	    uint Fitness;      // floatBitsToUint(fitness_float)
5	    uint MovesCount;
6	    uint Moves[GENES_COUNT];
7	    // DIAGNOSTIC (appended LAST so no existing offset shifts): the coherence piece-size histogram of the state at
8	    // the best step. 5 bits per bucket, bucket b = pieces with agreeAxes = b+1, i.e. of size 2^(N-1-b); counts
9	    // clamped at 31. 0 = not decomposed (no coherence / above the gateway). Host decodes it into "4+2" etc.
10	    uint Structure;
11	    // The INTEGER structure value the coherence accept compares -- the metric's integer term (currently
12	    // 2*(P2+N*S)) at the best step. The host reads THIS instead of re-deriving it, so changing the metric
13	    // lives entirely in EvaluateMicro (one line) and never needs a matching edit on the C# side.
14	    uint Ladder;
15	};
16	
17	struct Move
18	{
19	    uint Axis;
20	    uint Slice;
21	    uint Plane;
22	    uint Angle;
23	};
24	
25	Move getMove(uint code)
26	{
27	    uint angle = code & 3u;
28	    uint plane = (code >> 2u) & 31u;
29	    uint axis = (code >> 7u) & 7u;
30	    uint slice = code >> 10u;
31	    return Move(axis, slice, plane, angle);
32	}
33	
34	// Inverse move: keep axis/plane/slice, negate the angle in quarter-turns (1<->3, 2 and 0 stay).
35	// Matches TMove.GetRevCode. Shared by Init (commutator [S,R]) and SelCrossover (commutator [M,D]).
36	uint getRevCode(uint code) {
37	    return (code & ~3u) | ((4u - (code & 3u)) & 3u);
38	}
39	
40	// Fast bitwise hash for randomness generation (shared by Init and SelCrossover)
41	uint hash(uint x) {
42	    x = ((x >> 16) ^ x) * 0x45d9f3bu;
43	    x = ((x >> 16) ^ x) * 0x45d9f3bu;
44	    x = (x >> 16) ^ x;
45	    return x;
46	}
47	
48	// 2. Central buffer registry
49	layout(std430, binding = 0) buffer PopulationBuffer { Specimen Population[]; };
50	layout(std430, binding = 1) buffer NewPopulationBuffer { Specimen NewPopulation[]; }; // Crossover output (ping-pong with Population)
51	layout(std430, binding = 2) buffer CubiesBuffer { uint Cubies[]; };
52	layout(std430, binding = 3) buffer FreeMovesBuffer { uint FreeMoves[]; };
53	layout(std430, binding = 4) buffer SolvedBuffer { uint SolvedCubies[]; };
54	layout(std430, binding = 5) buffer ActiveBuffer { uint ActiveCubies[]; };
55	layout(std140, binding = 6) uniform PlanesBuffer { ivec2 Planes[PLANES_COUNT]; };
56	layout(std430, binding = 7) buffer SeedBuffer { uint SeedMoves[]; };   // Init: per-specimen seed sequences
57	
58	// 3. Uniform location registry
59	//layout(location = 0) uniform uint N;
60	//layout(location = 1) uniform uint SIZE;
61	//layout(location = 2) uniform uint CUBIES_COUNT; // SIZE^N
62	//layout(location = 3) uniform uint PLANES_COUNT;
63	layout(location = 0) uniform uint TimeSeed;
64	// Cluster sizes come from the host, not buffer .length(): a first cluster has an empty SolvedCubies
65	// buffer, and .length() on a zero-size SSBO is unreliable across drivers.
66	layout(location = 4) uniform uint countSolved;
67	layout(location = 5) uniform uint countActive;
68	layout(location = 2) uniform uint u_Stage;
69	layout(location = 3) uniform uint u_PassModStage;
70	layout(location = 6) uniform uint numSeeds;   // Init: number of specimens pre-seeded from SeedMoves
71	// Coherence LATCH THRESHOLD, reused as the endgame NORMALIZER base. A uniform (single source of truth =
72	// Gpu.Floor), so the host and the evaluator can never disagree. It no longer WALKS -- it is the fixed floor
73	// (FloorStart) that (a) the host uses to trip Coherent 0->1 and (b) the factor divides by, as FLOOR * N, to
74	// pin the scattered floor state to fitness 1.0.
75	layout(location = 7) uniform uint FLOOR;
76	// Coherence LATCH (0/1). A uniform, not a #define, so the phase switch costs no shader rebuild: the host keeps it
77	// 0 through the count-peel descent and sets it to 1 once the active cluster's residual reaches the floor. When 0
78	// the evaluator is the bare per-cubie count; when 1 the endgame coherence discount applies (scrambled <= gateway).
79	layout(location = 8) uniform uint COHERENT;
80	
81	
82	void getRow(uint M, uint row, out uint outCol, out int outSign)
83	{
84	    uint rowData = (M >> (row * BITS_PER_ROW)) & ((1u << BITS_PER_ROW) - 1u);
85	
86	    outCol = rowData & ((1u << BITS_FOR_COL) - 1u);
87	    outSign = ((rowData >> BITS_FOR_COL) & 1u) == 1u ? -1 : 1;
88	}
89	
90	uint setRow(uint M, uint row, uint col, int sign)
91	{
92	    uint signBit = (sign == -1) ? 1u : 0u;
93	    uint rowData = (signBit << BITS_FOR_COL) | (col & ((1u << BITS_FOR_COL) - 1u));
94	    uint shift = row * BITS_PER_ROW;
95	    uint mask = ((1u << BITS_PER_ROW) - 1u) << shift;
96	    return (M & ~mask) | (rowData << shift);
97	}
98	
99	void RotateMatInt(inout uint M, uint axis1, uint axis2, uint angleStep)
100	{
101	    // Extract only the two rows we care about, which form the rotation plane
102	    uint col1, col2;
103	    int sign1, sign2;
104	    getRow(M, axis1, col1, sign1);
105	    getRow(M, axis2, col2, sign2);
106	
107	    // angleStep is the number of quarter-turns: 0 = identity (no rotation), 1/2/3 = 90/180/270.
108	    if (angleStep == 1)      // 90 degrees left
109	    {
110	        M = setRow(M, axis1, col2, -sign2);
111	        M = setRow(M, axis2, col1, sign1);
112	    }
113	    else if (angleStep == 2) // 180 degrees
114	    {
115	        M = setRow(M, axis1, col1, -sign1);
116	        M = setRow(M, axis2, col2, -sign2);
117	    }
118	    else if (angleStep == 3) // 270 degrees (90 degrees right)
119	    {
120	        M = setRow(M, axis1, col2, sign2);
121	        M = setRow(M, axis2, col1, -sign1);
122	    }
123	}
124	
125	uint getStartCoordinate(uint cubieID, uint col)
126	{
127	    // Home coordinate along dimension col. The CPU linear index (TMatrix.Coords2Index) is
128	    // coords[0]*SIZE^(N-1) + ... + coords[N-1], so axis col has stride SIZE^(N-1-col), i.e. axis 0
129	    // is the most significant digit. This keeps the shader's axis numbering identical to the CPU's.
130	    uint shift = N - 1u - col;
131	    if (SIZE == 2)
132	        return (cubieID >> shift) & 1u; // Fast bitwise op for SIZE = 2
133	    else
134	    {
135	        uint divisor = 1u;
136	        for (uint i = 0u; i < shift; i++)
137	            divisor *= SIZE;
138	        return (cubieID / divisor) % SIZE;
139	    }
140	}
141	
142	// Current coordinate of a cubie along a given axis - the layer index a move on that axis addresses.
143	// Mirrors the currentLayer computation in TurnSingleCubie: the axis row picks a column, its home
144	// coordinate along that column, flipped when the axis is reflected. Two cubies sharing this value on
145	// SOME axis lie in a common layer, so one turn of that layer moves them together.
146	uint curCoord(uint M, uint cubieID, uint axis) {
147	    uint col;
148	    int sign;
149	    getRow(M, axis, col, sign);
150	    uint start = getStartCoordinate(cubieID, col);
151	    return (sign == 1) ? start : (SIZE - 1u) - start;
152	}
153	
154	// BINARY SIDE of a coordinate within its reflection pair {v, SIZE-1-v}: 0 for the low half, 1 for the high.
155	// A layer rotation maps v <-> SIZE-1-v, so within a cluster each axis is effectively BINARY (a +/- pair) and the
156	// cluster is "2^N cubies on a larger orbit". The coherence decomposition works in this SIDE-space, so it stays
157	// 2-based (ladder + gateway binary) for ANY SIZE. SIZE=2 -> identity (0->0, 1->1).
158	uint coordSide(uint M, uint cubieID, uint axis) {
159	    return (2u * curCoord(M, cubieID, axis) >= uint(SIZE)) ? 1u : 0u;
160	}
161	
162	uint TurnSingleCubie(uint cubieMatrix, uint cubieID, Move move) {
163	    uint col;
164	    int sign;
165	    getRow(cubieMatrix, move.Axis, col, sign);
166	    uint startLayerIndex = getStartCoordinate(cubieID, col);
167	    uint currentLayer = (sign == 1) ? startLayerIndex : (SIZE - 1) - startLayerIndex;
168	    if (currentLayer == move.Slice) {
169	        uint axis1 = Planes[move.Plane].x;
170	        uint axis2 = Planes[move.Plane].y;
171	        RotateMatInt(cubieMatrix, axis1, axis2, move.Angle);
172	    }
173	    return cubieMatrix;
174	}
175	
176	// L1 (Manhattan) distance of a packed orientation matrix from IDENTITY.
177	// The identity row r encodes (col = r, sign = +), i.e. field value r; a solved cubie -> 0. The sign
178	// is kept on the high bit of the field, so a reflected axis differs by 2^BITS_FOR_COL (>= N),
179	// dominating any column displacement (the "largest difference") so distinct orientations do not
180	// collide to the same L1.
181	uint cubieL1(uint M) {
182	    uint dist = 0u;
183	    for (uint r = 0u; r < uint(N); r++) {
184	        uint field = (M >> (r * BITS_PER_ROW)) & ((1u << BITS_PER_ROW) - 1u);
185	        dist += (field > r) ? (field - r) : (r - field);
186	    }
187	    return dist;
188	}
189	
190	// Number of axes the orientation does not leave fixed (row r != identity value r). A cubie needs
191	// m - 1 moves to solve (Givens spanning tree of its active axes), so m is a moves-to-solve measure.
192	uint activeAxes(uint M) {
193	    uint m = 0u;
194	    for (uint r = 0u; r < uint(N); r++) {
195	        uint field = (M >> (r * BITS_PER_ROW)) & ((1u << BITS_PER_ROW) - 1u);
196	        if (field != r) m++;
197	    }
198	    return m;
199	}
200	
201	// Per-cubie penalty: moves-to-solve (active axes, dominant) refined by L1 orientation distance.
202	// 0 <=> solved. m dominates because each active axis is weighted above the whole L1 range, so the
203	// search minimises the number of moves first, then the orientation distance within that.
204	uint cubieState(uint M) {
205	    return activeAxes(M) * (uint(MAX_CUBIE_L1) + 1u) + cubieL1(M);
206	}
207	
208	// SOLVED break-check by REPLAY (unified-evaluator direction): a Solved cubie is "broken" if the specimen's first
209	// prefixLen moves do NOT compose to identity on it. Replay those moves on ONE cubie -- start from its GA-start state
210	// Cubies[id] (identity for a Solved cubie), apply TurnSingleCubie step by step -- with O(1) storage, so we never need
211	// all Solved states in registers at once. This is what lets the evaluator hold ONLY the active cluster instead of the
212	// whole cube. Returns the count of broken Solved cubies (>=1 -> the move breaks a solved cluster -> host rejects).
213	uint solvedBrokenCount(uint specimenID, uint prefixLen) {
214	    uint broken = 0u;
215	    for (uint i = 0u; i < countSolved; i++) {
216	        uint id = SolvedCubies[i];
217	        uint mat = Cubies[id];
218	        for (uint m = 0u; m < prefixLen; m++)
219	            mat = TurnSingleCubie(mat, id, getMove(Population[specimenID].Moves[m]));
220	        if (cubieL1(mat) != 0u) broken++;
221	    }
222	    return broken;
223	}
224	
225	float GetActiveCubieError(uint cubieMatrix, float maxClusterState, float max_fA) {
226	    uint d = cubieState(cubieMatrix);
227	    // D4: smooth (cliff-free) base. The cliff form (maxClusterState + d)/max_fA adds a big fixed premium per
228	    // scrambled cubie, so fA is essentially a COUNT and the floor plateau below T is flat -> STALL blind-walks
229	    // out of it (the D3 tail). This form charges only the magnitude d/maxClusterState, giving the floor a
230	    // sub-gradient toward less twist = toward solved. Trade-off: it is a GLOBAL change (mid-game homing loses
231	    // the cliff, may slow) and the floor's count-block softens. A/B against the cliff form above.
232	    //return float(d) / maxClusterState;
233	    return d == 0u ? 0.0 : (maxClusterState + float(d)) / max_fA;
234	}
