4	// 1 thread = 1 specimen. A block of 64 threads processes 64 specimens at once.
5	layout(local_size_x = 64) in;
6	
7	void main()
8	{
9	    uint specimenID = gl_GlobalInvocationID.x;
10	    if (specimenID >= Population.length()) return;
11	
12	    float maxClusterState = float(MAX_CUBIE_STATE) * float(countActive);
13	    float max_fA = maxClusterState *(float(countActive) + 1.0);
14	
15	    // Per-thread (per-specimen) records initialized to the maximum float value
16	    float specimen_best_fitness = 1e38;
17	    uint specimen_best_moves_count = 0;
18	    uint specimen_best_structure = 0u;                   // DIAGNOSTIC: piece histogram at the best step (see Setup)
19	    uint specimen_best_ladder = 0u;                      // ACCEPT metric: integer structure value at the best step (Setup: Ladder)
20	
21	    // CUBE IN REGISTERS: thread-private array mapped to ultra-fast ALU registers.
22	    // Cubies holds the shared read-only starting state; each thread copies it into its private
23	    // working array and mutates only that copy, so the single shared buffer is race-free.
24	    uint local_active[MAX_CLUSTER];                  // ONLY the active cluster in registers (not the whole cube) -> cube-size-independent
25	    for (uint i = 0; i < countActive; i++)
26	        local_active[i] = Cubies[ActiveCubies[i]];
27	
28	    uint cut = min(Population[specimenID].MovesCount, uint(GENES_COUNT));   // evaluate ONCE at the genome's cut (Init picks seed-cut OR commutator-cut per specimen; crossover -> commutator-cut)
29	    for (int m = 0; m < int(cut); m++)
30	    {
31	        Move move = getMove(Population[specimenID].Moves[m]);
32	
33	        // 2a. CUBE ROTATION: the thread modifies only its own private registers
34	        for (uint i = 0; i < countActive; i++)
35	            local_active[i] = TurnSingleCubie(local_active[i], ActiveCubies[i], move);
36	    }
37	
38	        // 2b. EVALUATION -- ONCE, on the final cut state (not per prefix): sum the active-cluster errors
39	        float local_fA_sum = 0.0;
40	        uint scrambled = 0u;
41	        bool changed = false;
42	        uint structure = 0u;                              // piece histogram for THIS step (0 = not decomposed)
43	        uint ladder = 0u;                                 // integer structure value for THIS step (0 = solved/descent, the best possible)
