322	            ////    structure = min(scrambled, 31u) << (5u * (uint(N) - 1u));
323	            ////}
324	            ////local_fA_sum = (float(ladder) + local_fA_sum) / float(NORM * (countActive + 1u));
325	
326	            //local_fA_sum *= (float(2u * P2 * S) + 1 - Cnorm) / float((uint(N) * (uint(N) + 1u)) * scrambled);   // 2*P2*S + coupling, K=2
327	            // MEASURE P2 * S + E2: adds depth-weighted empty partners. Breaks the k+0=k+k and 2+1+1=2+1+0 rung ties
328	            // (E2 penalizes incomplete pairings) -- A/B vs pure P2*S. Floor (4 singletons, N=4): P2*S=14, E2=3 -> 17.
329	            //local_fA_sum *= float(P2 * S + E2) / float((uint(N) * (uint(N) + 3u) / 2u + 3u) * scrambled);   // +3u = E2 at the 4-singleton floor (2^4)
330	            //local_fA_sum *= (cost + collat) / sqrt(float(81) * float(scrambled));   // suma/(G*N): no /s, no sqrt (baseline)
331	            // PAIR: tip the k+0 vs k+k rung. Fires only on exactly two equal blocks of size >= 2 (2+2, 4+4, 8+8) --
332	            // nothing else. PAIR=EQUAL (the default, = 1.0) is a no-op: k+0 and k+k already tie in suma. See Variables.
333	            //if (pieces == 2u && bitCount(seenAgree) == 1u && aMax < uint(N))
334	            //    local_fA_sum *= float(PAIR);
335	
336	            // ---------------------------------------------------------------------------------------------------
337	            // ALTERNATIVE, kept for A/B -- the LADDER metric. To switch: comment out the block above, uncomment
338	            // this one, replace the `aMax`/`seenAgree` declarations with `float invSum = 0.0;` and, in the
339	            // FULLY-filled branch of the loop, replace their two updates with   invSum += 1.0 / float(cnt);
340	            //
341	            // It grows structure toward the gateway instead of shrinking the residual. With d_i the piece sizes,
342	            // m their count and s = scrambled, the discount is 4*SUM(1/d_i)/s^2, and since base ~ s/(countActive+1)
343	            // the FITNESS comes out ~ 4/(m*d^2) for m equal blocks of size d. The whole ladder is then ONE
344	            // invariant: every rung DOUBLES m*d^2 -- adding a symmetric partner doubles m, merging a pair halves m
345	            // and doubles d (1/2 * 4 = 2) -- so the fitness halves at every rung, with no symmetry factor and no
346	            // special cases. On 2^5, in units of 1/(countActive+1):
347	            //     1+1 2 > 2+0 1 > 2+2 .5 > 4+0 .25 > 4+4 .125 > 8+0 .0625 > 8+8 .031 > 16+0 .016
348	            // The s^2 (not s) matters: base is ~s, so a single factor of s only cancels the base and leaves the
349	            // doubling rungs TIED. Writing the discount as SUM(1/d)/s^c, a merge always scales the fitness by 1/2
350	            // whatever c is, a doubling by 2^(1-c) and a descent among SCATTERED cubies by 2^(c-1) -- the last two
351	            // are structurally the SAME event (m doubles at fixed d) and demand OPPOSITE sides of c=1, so no
352	            // exponent gives both. c=2 picks the ladder, at the price that inside the gateway the search stops
353	            // wanting to peel at all. UNMEASURED against the baseline above.
354	            //
355	            // float s = float(scrambled);
356	            // local_fA_sum *= 4.0 * invSum / (s * s);
357	            // ---------------------------------------------------------------------------------------------------
358	        }
359	
360	        // The factor is P2 * S -- P2 = depth-weighted sum over the PARENT nodes (empty partners excluded, root
361	        // weighted depth+1), S = number of distinct block sizes. Count-cancelled by /scrambled so the endgame
362	        // reads as the bare P2*S / (N(N+3)/2): scattered floor (P2 = N(N+3)/2, S = 1) is 1.0. FLOOR (uniform 7)
363	        // is now ONLY the host-side latch threshold -- the factor no longer reads it (dead-uniform cleanup
364	        // pending). On the descent (Coherent = 0) this block is skipped; the bare count peels.
365	        // (aMax/aSum/m2 still in history but unused -- earlier variants kept commented for A/B.)
366	        // UNIFIED: per-step fitness is ACTIVE-only (metric + no-op). The Solved break-check is DEFERRED to the best
367	        // step and done by replay after the loop -- so no whole-cube solved read here. (Best step is chosen without
368	        // the break: CONSERVATIVE. If it later breaks a Solved cubie, the replay penalty pushes fitness >= 1 -> reject.)
369	        float current_step_fitness = local_fA_sum;
370	        if (!changed) current_step_fitness += float(2 * CUBIES_COUNT);   // no-op on the active cluster: rank below every real move (max real fitness <= CUBIES_COUNT, since solved+active = CUBIES_COUNT and the active term <= 1)
371	        specimen_best_fitness = current_step_fitness;
372	        specimen_best_moves_count = cut;                  // the cut IS the answer -- no scan, no best-of-prefixes
373	        specimen_best_structure = structure;
374	        specimen_best_ladder = ladder;
375	    // SOLVED break-check at the BEST step, by per-cubie replay (O(1) storage each -- see solvedBrokenCount). A broken
376	    // Solved cubie adds 1, pushing fitness >= 1 so the host rejects the move. On single-cluster cubes (2^4) countSolved
377	    // = 0, so this is a no-op and results are IDENTICAL to the old per-step solved loop -> clean 2^4 regress-guard.
378	    specimen_best_fitness += float(solvedBrokenCount(specimenID, specimen_best_moves_count));
379	
380	    // 3: Write the record back to the population
381	    Population[specimenID].Fitness = floatBitsToUint(specimen_best_fitness);
382	    Population[specimenID].MovesCount = specimen_best_moves_count;
383	    Population[specimenID].Structure = specimen_best_structure;
384	    Population[specimenID].Ladder = specimen_best_ladder;
385	}
