#version 430
#include "Setup.glsl.c"

// One thread produces one child specimen. With MUTATION_RATIO% probability the child is a fresh cubie-solver
// commutator RE-SEEDED from the frozen seed archive (the macro mutation); otherwise it is a commutator CROSSOVER of
// two rank-selected parents. Parents are read from Population (binding 0), already sorted ascending by fitness by the
// bitonic sort. Children are written to NewPopulation (binding 6).
layout(local_size_x = 64) in;

void main() {
    uint cid = gl_GlobalInvocationID.x;
    if (cid >= POPULATION_COUNT) return;

    uint seed = cid ^ TimeSeed;
    uint freeMovesCount = uint(FreeMoves.length());

    uint child[GENES_COUNT];
    uint movesCount;

    // RE-SEED mutation (replaces the perturbing mutation, and the ONLY mutation operator): with MUTATION_RATIO%
    // probability the child is NOT a crossover but a fresh cubie-solver drawn from the frozen SeedMoves archive and
    // built EXACTLY as Init builds a seeded specimen -- a break-free commutator [S,R] = S R S^-1 R^-1, cut at the seed
    // end (MovesCount = |S|, the PEEL cut). This is the macro-operator that RE-INJECTS building blocks selection has
    // dropped as the population drifts away from generation 0 -- the endgame findability lever. Mirroring Init keeps a
    // single definition of "a seeded specimen": a re-seeded child is indistinguishable from a gen-0 one, so it passes
    // the break-check and is evaluated at its real cut. (The OLD reseed pasted a RAW seed and set MovesCount = 0, which
    // the unified evaluator scores at cut 0 = no-op = a dead child ranked last; this does not.)
    if (numSeeds > 0u && hash(seed + 8u) % 100u < uint(MUTATION_RATIO)) {
        uint base = (hash(seed + 9u) % numSeeds) * SEED_STRIDE;
        uint sLen = 0u;
        for (; sLen < SEED_STRIDE; sLen++) {                                              // S
            uint code = SeedMoves[base + sLen];
            if (code == 0xFFFFFFFFu) break;
            child[sLen] = code;
        }
        uint rLen = 1u + hash(seed + 10u) % uint(N - 1);                                  // R length 1..N-1
        uint pos = sLen;
        for (uint r = 0u; r < rLen && pos < GENES_COUNT; r++, pos++)                      // R (random free moves)
            child[pos] = FreeMoves[hash(seed + 200u + r) % freeMovesCount];
        for (int i = int(sLen) - 1; i >= 0 && pos < GENES_COUNT; i--)                     // S^-1
            child[pos++] = getRevCode(child[i]);
        for (int i = int(sLen + rLen) - 1; i >= int(sLen) && pos < GENES_COUNT; i--)      // R^-1
            child[pos++] = getRevCode(child[i]);
        movesCount = sLen;                                                                // seed cut, as Init (PEEL)
        for (uint g = pos; g < GENES_COUNT; g++)                                          // dormant tail: random free moves
            child[g] = FreeMoves[hash(seed + g) % freeMovesCount];
    } else {
        // CROSSOVER: rank selection + commutator [M,D] = M D M^-1 D^-1 of two distinct parents.
        // Rank selection: draw two distinct parents from the top WINNERS_RATIO percent.
        uint winnerCount = (POPULATION_COUNT * WINNERS_RATIO) / 100u;
        if (winnerCount < 2u) winnerCount = 2u;
        uint momIdx = hash(seed + 1u) % winnerCount;
        uint dadIdx = (momIdx + 1u + hash(seed + 2u) % (winnerCount - 1u)) % winnerCount;

        // Split point in the first half. Mirrors CPU: Rnd.Next(GENES_COUNT) / 2.
        uint startPos = (hash(seed + 3u) % GENES_COUNT) / 2u;
        uint stopPos = startPos + 1u + hash(seed + 4u) % uint(N - 1);
        if (stopPos > GENES_COUNT / 2u) stopPos = GENES_COUNT / 2u;

        // 1. Build the first part with a single write per gene (no redundant full-mom copy):
        //    mom prefix [0, startPos), then dad's middle [startPos, stopPos).
        for (uint i = 0u; i < startPos; i++)
            child[i] = Population[momIdx].Moves[i];
        for (uint i = startPos; i < stopPos; i++)
            child[i] = Population[dadIdx].Moves[i];

        // 2. second half = reverse-complement of the first part: the mom block [0,startPos)
        //    and the dad block [startPos,stopPos), each reversed with negated angles -> commutator [M,D].
        movesCount = stopPos;
        for (int i = int(startPos) - 1; i >= 0; i--)
            child[movesCount++] = getRevCode(child[i]);
        for (int i = int(stopPos) - 1; i >= int(startPos); i--)
            child[movesCount++] = getRevCode(child[i]);

        // 3. mom's tail beyond the reversible core [2*stopPos, GENES_COUNT) stays as mom (as on the CPU).
        for (uint i = 2u * stopPos; i < GENES_COUNT; i++)
            child[i] = Population[momIdx].Moves[i];
    }

    // 4. write the child out; fitness is recomputed by the evaluate shader next generation.
    for (uint i = 0u; i < GENES_COUNT; i++)
        NewPopulation[cid].Moves[i] = child[i];
    NewPopulation[cid].Fitness = floatBitsToUint(1e38);
    NewPopulation[cid].MovesCount = movesCount;
}

