// Solved cubie adds 1, pushing fitness >= 1 so the host rejects the move. On single-cluster cubes (2^4) countSolved
// = 0, so this is a no-op and results are IDENTICAL to the old per-step solved loop -> clean 2^4 regress-guard.
current_step_fitness += float(solvedBrokenCount(specimenID, m + 1));

input.new_string:
// SOLVED break-check: read the precomputed bit for this prefix (state after m+1 moves == bit m). A broken
// Solved cubie adds 1, pushing fitness >= 1 so the host rejects the move. On single-cluster cubes (2^4)
// countSolved = 0, so solvedBroken is all-zero here -> no-op, identical to before.
current_step_fitness += float((solvedBroken[uint(m) >> 5u] >> (uint(m) & 31u)) & 1u);

