1	#version 430
2	#include "Setup.glsl.c"
3	
4	// 1 thread = 1 specimen. A block of 64 threads processes 64 specimens at once.
5	layout(local_size_x = 64) in;
6	
7	void main()
8	{
9			uint specimenID = gl_GlobalInvocationID.x;
10			if (specimenID >= Population.length()) return;
11	
12			float maxClusterState = float(MAX_CUBIE_STATE) * float(countActive);
13			float max_fA = maxClusterState * (float(countActive) + 1.0);
14	
15			// Per-thread (per-specimen) records initialized to the maximum float value
16			float specimen_best_fitness = 1e38;                  // SORT/breed key: coherence-rewarded selFitness
17			float specimen_best_peel = 1e38;                     // (b) PEEL score (base, pre-coherence) at the best-selFitness step -- the ACCEPT reference, written to the Ladder slot
18			uint specimen_best_moves_count = 0;
19			uint specimen_best_structure = 0u;                   // DIAGNOSTIC: piece histogram at the best step (see Setup)
20			uint specimen_best_ladder = 0u;                      // ACCEPT metric: integer structure value at the best step (Setup: Ladder)
21	
22			// CUBE IN REGISTERS: thread-private array mapped to ultra-fast ALU registers.
23			// Cubies holds the shared read-only starting state; each thread copies it into its private
24			// working array and mutates only that copy, so the single shared buffer is race-free.
25			uint local_active[MAX_CLUSTER];                  // ONLY the active cluster in registers (not the whole cube) -> cube-size-independent
26			for (uint i = 0; i < countActive; i++)
27					local_active[i] = Cubies[ActiveCubies[i]];
28	
29			uint cut = min(Population[specimenID].MovesCount, uint(GENES_COUNT));   // evaluate ONCE at the genome's cut (Init picks seed-cut OR commutator-cut per specimen; crossover -> commutator-cut)
30	
31			// SOLVED break-check, precomputed for EVERY prefix in ONE forward pass per Solved cubie (replaces the old
32			// per-prefix re-replay: O(countSolved * GENES) instead of O(countSolved * GENES^2), still O(1) storage per
33			// cubie -- one at a time). Bit g == "some Solved cubie is broken (non-identity) after the first g+1 moves".
34			// One 32-bit word per 32 genes, so GENES_COUNT > 32 just adds words. countSolved == 0 (single-cluster cubes
35			// like 2^4 / 2^5) leaves it all-zero -> no penalty, identical to before.
36			uint solvedBroken[(GENES_COUNT + 31) / 32];
37			for (uint w = 0u; w < (GENES_COUNT + 31u) / 32u; w++) solvedBroken[w] = 0u;
38			for (uint s = 0u; s < countSolved; s++) {
39					uint id = SolvedCubies[s];
40					uint mat = Cubies[id];
41					for (uint g = 0u; g < uint(GENES_COUNT); g++) {
42							mat = TurnSingleCubie(mat, id, getMove(Population[specimenID].Moves[g]));
43							if (cubieL1(mat) != 0u) solvedBroken[g >> 5u] |= 1u << (g & 31u);
44					}
45			}
46	
47			for (int m = 0; m < GENES_COUNT; m++)
48			{
49					Move move = getMove(Population[specimenID].Moves[m]);
50	
51					// 2a. CUBE ROTATION: the thread modifies only its own private registers
52					for (uint i = 0; i < countActive; i++)
53							local_active[i] = TurnSingleCubie(local_active[i], ActiveCubies[i], move);
54					// 2b. EVALUATION: sum the active-cluster errors
55					float local_fA_sum = 0.0;
56					uint scrambled = 0u;
57					uint structure = 0u; // piece histogram for THIS step (0 = not decomposed)
58					uint NORM = 1u * (FLOOR - 1u + uint(N - findMSB(FLOOR)));   // floor value of 2*P at all-singletons FLOOR
59					NORM *= countActive + 1u;
60					//if (COHERENT == 0u)
61					//{
62					bool changed = false;
63					for (uint i = 0; i < countActive; i++) {
64							uint cur = local_active[i];
65							if (cur != Cubies[ActiveCubies[i]]) changed = true;   // did this prefix move the active cluster?
66							float e = GetActiveCubieError(cur, maxClusterState, max_fA);
67							if (e != 0.0) scrambled++;
68							// ENDGAME (COHERENT): the base is BINARY -- solved (0) or not (1). Structurally-equal configs then
69							// tie EXACTLY, and the count cancels the factor's /scrambled, so fitness = the PURE coherence factor.
70							// That lets the accept rule step SIDEWAYS between equally-valued structures (the ties finally fire).
71							// DESCENT (COHERENT 0): keep the graded per-cubie error so the count-peel keeps its gradient.
72							//local_fA_sum += (COHERENT != 0u) ? (e != 0.0 ? 1.0 / float(countActive + 1) : 0.0) : e;
73							local_fA_sum += e;
74					}
75					if (!changed) local_fA_sum += 2 * CUBIES_COUNT;   // ~0,2 -> ~32,2
76					uint ladder = uint(local_fA_sum * float(NORM)); // integer structure value for THIS step (0 = solved/descent, the best possible)
77					if (scrambled > 0 && scrambled < FLOOR)
