443	        public List<int> GetClusterMoves()
444	        {
445	            var pos = ActiveCubie.Position;
446	
447	            // slice'y dotykane przez KT�RYKOLWIEK kubik aktywnego klastra: klaster to orbita
448	            // (permutacje osi + odbicia) aktywnego kubika, wi�c jego warto�ci wsp�rz�dnych + lustra
449	            // daj� ca�y zakres slice'�w klastra.
450	            // Podw�jny zapis do tej samej kom�rki jest bezpieczny (m.in. �rodek przy nieparzystym SIZE).
451	            var validSlices = new bool[Size];
452	            for (int coord = 0; coord < TAffine.N; coord++)
453	            {
454	                validSlices[pos[coord]] = true;
455	                validSlices[Size - 1 - pos[coord]] = true;
456	            }
457	            var clusterMoves = new List<int>();
458	            var move = new TMove();
459	            for (move.Slice = 0; move.Slice < Size; move.Slice++)
460	            {
461	                if (!validSlices[move.Slice]) continue;
462	                for (move.Plane = 0; move.Plane < TAffine.Planes.Length; move.Plane++)
463	                {
464	                    var planeAxes = TAffine.Planes[move.Plane];
465	                    for (move.Axis = 0; move.Axis < TAffine.N; move.Axis++)
466	                    {
467	                        if (move.Axis == planeAxes[0] || move.Axis == planeAxes[1]) continue;
468	                        for (move.Angle = 1; move.Angle < 4; move.Angle++)
469	                            clusterMoves.Add(move.Encode());
470	                    }
471	                }
472	            }
473	            return clusterMoves;
474	        }
