480	        // The Solved cubies that the active cluster's free moves can actually TOUCH: those with >=1 coord in
481	        // validSlices (the cluster's coord values + mirrors = exactly the layers ClusterMoves turns; validSlices is
482	        // orbit-invariant, so the active cubie's current position gives the same set as its home). A solved cubie
483	        // outside every valid slice is never in a turned layer -> can never break, so the GPU break-check may SKIP it.
484	        // Safe because ALL genes stay within validSlices: Init draws FreeMoves, crossover recombines, and seed moves
485	        // have Slice = a cluster cubie's coord (always in validSlices). Computed ONCE per cluster (in NextCluster).
486	        void ComputeSolvedInSlices()
487	        {
488	            var pos = ActiveCubie.Position;
489	            var validSlices = new bool[Size];
490	            for (int coord = 0; coord < TAffine.N; coord++)
491	            {
492	                validSlices[pos[coord]] = true;
493	                validSlices[Size - 1 - pos[coord]] = true;
494	            }
495	            SolvedInSlices = new List<TCubie>();
496	            foreach (var s in SolvedCubies)
497	            {
498	                var sp = s.Position;
499	                for (int coord = 0; coord < TAffine.N; coord++)
500	                    if (validSlices[sp[coord]]) { SolvedInSlices.Add(s); break; }
501	            }
502	        }
