526	        // Accumulated GA COMPUTE time (GPU work + orchestration) across all GetNextMoves steps of the current
527	        // solve -- the piece the generation count hides: coherence-on steps cost far more than count-peel steps.
528	        // Reset per solve; read by the form for display and by the batch for per-run timing.
529	        public readonly System.Diagnostics.Stopwatch ComputeTime = new System.Diagnostics.Stopwatch();
530	
531	        public void Reset()
532	        {
533	            IterationsCount = 0;
534	            Score = 0;
535	            ActiveCubie = null;
536	            ComputeTime.Reset();
537	        }
