539	        // ONE GA decision step -- Runs in BOTH phases
540	        // (the count-peel descent AND the post-floor coherence climb). It:
541	        //   1. re-selects the target cubie -- UNSOLVED one of the active cluster -- which is what lets
542	        //      successive GA runs during a stall attack the SAME configuration from different cubies;
543	        //   2. advances to the next cluster when the current one is solved (descent phase, base floor);
544	        //   3. runs one GA and applies the STALL accept test (accept strictly-better always, equal only after
545	        //      StallLimit consecutive non-improving runs -- a gated sideways step off a plateau).
546	        // Returns the accepted moves (empty if none, or if the whole cube is solved -> Best == null).
547	        public List<TMove> GetNextMoves()
548	        {
549	            ComputeTime.Start();                       // accumulate GA compute time (paired Stop before EVERY return)
550	            var moves = new List<TMove>();
551	            if (Score == 0)                            // current cluster solved -> advance
552	                NextCluster();
553	            if (ActiveCubie == null) // whole cube solved
554	            {
555	                Best = null;
556	                ComputeTime.Stop();
557	                return moves;
558	            }
559	            Scrambled = 0;
560	            foreach (var c in ActiveCluster) if (c.State != 0) Scrambled++;
561	            // COHERENCE LATCH (no walk). Two phases: during the DESCENT coherence is OFF, so the evaluator is the
562	            // bare count and the peel drives the residual down fast; once the active cluster's residual reaches the
563	            // floor (base 4), latch coherence ON for the ENDGAME and leave it on for the rest of the cluster. The
564	            // floor is now ONLY this latch threshold -- it never walks. Count-cancellation lives inside the metric
565	            // (the /scrambled in the coherence factor), so once latched the fitness is the bare coherence factor
566	            // for the whole endgame (0 < scrambled <= G) and the yardstick never jumps. The latch itself DOES
567	            // switch metrics (count -> factor), so RubikCube.Score (the accept-test reference) is re-measured once,
568	            // at the flip. Reset to descent (coherence OFF, floor 4) per cluster in Solve(). Called after the moves
569	            // are applied, when the cube IS the state just reached.
570	            // COHERENCE LATCH by TWO conditions, Floor gating BOTH (single knob): coherence is the ENDGAME escape hatch,
571	            // engaged only when (1) the residual is SMALL -- Scrambled < Floor, so its decomposition is cheap and
572	            // meaningful (never invoked on a large scattered residual, where it struggles) AND (2) the peel is STUCK
573	            // there -- Stall > Floor, i.e. score has NOT strictly dropped for > Floor runs. Floor is no longer a lone
574	            // trigger (that prematurely latched, e.g. the 9th-cluster stall); it now bounds size AND stall together.
575	            // Latched once -> stays on for the cluster; the metric switch (count -> ladder) rebases Score here once.
576	            if (Gpu.Coherent == 0 && Scrambled <= (int)Gpu.Floor) // && Stall > (int)Gpu.Floor)
577	            {
578	                Gpu.Coherent = 1;
579	                Score = Gpu.ScoreCube(this);
580	                ScoreLadder = Gpu.LastScoreLadder;
581	                Stall = 0;
582	            }
583	            // advance target: DETERMINISTIC round-robin --  // the next UNSOLVED cubie of the cluster after the
584	            var cluster = ActiveCluster;           // current one (wrapping). Cluster order is stable
585	            int cur = cluster.IndexOf(ActiveCubie);// (Cubies array order), so successive steps cycle
586	            for (int step = 1; step <= cluster.Count; step++)// through all cubies once per pass -- no coupon-
587	            {                                                // collector waste of the old random pick, and it
588	                var cand = cluster[(cur + step) % cluster.Count];  // pairs exactly with StallLimit = #unsolved.
589	                if (cand.State != 0) { ActiveCubie = cand; break; }
590	            }
591	            TRubikGenome.RubikCube = this;
592	            var candidate = Gpu.ExecuteGA();   // fresh GA result; Best (the displayed/accepted state) advances ONLY on accept
593	            // Accept EQUAL fitness too (<=), not only strictly-better: a sideways move on the plateau, but only
594	            // after a full round-robin pass with no improvement. Safe because the no-op penalty (2*CUBIES_COUNT)
595	            // makes standing still score ABOVE Score, so Fitness == Score is always a REAL move to a different
596	            // equal-fitness state. The stall budget is the number of UNSOLVED cubies: paired with the round-robin
597	            // target advance, that is exactly "try every cubie once; if none improved, step sideways" -- a
598	            // principled limit, not the old fixed 20 (STALL_LIMIT define is no longer read here).
599	            Stall++;
600	            // Accept: DESCENT compares the (fine) fitness; COHERENCE compares the STRUCTURE ladder value so
601	            // structurally-equal configs tie (sideways fire). The extra Best.Fitness < 1 gate rejects any move that
602	            // breaks a Solved cluster: the fitness is normalised to < 1, so Fitness >= 1 means solved_errors >= 1
603	            // (or a no-op) -- one test kills both, even on a sideways.
604	            // Accept: DESCENT compares the (fine) peel Fitness; COHERENT compares the STRUCTURE ladder so structurally-
605	            // equal configs TIE -> sideways fires, which is what escapes a peel LOCAL MINIMUM like the mono-twist (the move
606	            // mono[28] -> 2-block[20] raises the count but lowers the structure, so the ladder accepts it). Fitness < 1
607	            // rejects a Solved-breaker / no-op (Fitness is normalised < 1; >= 1 means a break or a stand-still). GA
608	            // SELECTION is separate: the sort breeds by Fitness, which in COHERENT is the PURE coherence factor.
609	            bool accept = Gpu.Coherent == 0
610	                ? candidate.Fitness < Score || candidate.Fitness == Score && Stall >= TGA<TRubikGenome>.StallLimit
611	                : candidate.Fitness < 1f && candidate.Ladder <= ScoreLadder;
612	            if (accept)
613	            //if (candidate.Fitness <= Score)
614	            {
615	                Best = candidate;   // ACCEPTED -> the displayed/state Best advances (untouched during Stall, so the label no longer flickers to rejected candidates)
616	                Best.Correct();
617	                for (int i = 0; i < Best.BestMovesCount; i++)
618	                    moves.Add(TMove.Decode((int)Best.Genes[i]));
619	                Stall = 0;
620	                //if (Best.Fitness < Score) Stall = 0;   // STRICT improvement -> reset (compare BEFORE overwriting Score, which still holds the OLD value); a sideways (== Score) keeps Stall growing toward the latch
621	                Score = Best.Fitness;
622	                if (Gpu.Coherent != 0) ScoreLadder = Best.Ladder;   // advance the coherent structure baseline
623	            }
624	            else if (Best == null) Best = candidate;   // first run before any accept: keep Best non-null (null == "whole cube solved" to Form1)
625	            ComputeTime.Stop();
626	            return moves;
627	        }
