629	        public void NextCluster()
630	        {
631	            Gpu.Coherent = 0;    // new cluster -> descent
632	            Stall = 0;           // fresh stall counter -> the new cluster's peel starts un-stalled (latch is per-cluster)
633	            if (ActiveCubie != null)
634	                SolvedCubies.AddRange(ActiveCluster);
635	            ActiveCubie = null;
636	            var minDist = int.MaxValue;
637	            foreach (var cubie in Cubies)
638	            {
639	                if (cubie.State == 0) continue;
640	                if (cubie.ClusterIndex < minDist)
641	                {
642	                    minDist = cubie.ClusterIndex;
643	                    ActiveCubie = cubie;
644	                }
645	            }
646	            activeCluster = null;
647	            if (ActiveCubie == null)
648	                SolvedCubies.Clear();
649	            else
650	            {
651	                RebuildClusterMoves();
652	                ComputeSolvedInSlices();   // bound the break-check to the Solved cubies these moves can touch (once per cluster)
653	                GetSolveSeq();
654	                Score = Gpu.ScoreCube(this);
655	            }
656	        }
