735	        static void Swap(ref int a, ref int b)
736	        {
737	            var temp = a;
738	            a = b;
739	            b = temp;
740	        }
741	
742	        static List<int[]> DoPermute(int[] nums, int start, int end)
743	        {
744	            var result = new List<int[]>();
745	            if (start == end)
746	            {
747	                var perm = new int[nums.Length];
748	                Array.Copy(nums, perm, nums.Length);
749	                result.Add(perm);
750	            }
751	            else
752	                for (var i = start; i <= end; i++)
753	                {
754	                    Swap(ref nums[start], ref nums[i]);
755	                    result.AddRange(DoPermute(nums, start + 1, end));
756	                    Swap(ref nums[start], ref nums[i]);
757	                }
758	            return result;
759	        }
