801	        public List<int> GetOrder()
802	        {
803	            var mask = new bool[TAffine.N, TAffine.N];
804	            var planes = new List<int>();
805	            for (int i = 0; i < TAffine.Planes.Length; i++)
806	                planes.Add(i);
807	            var caseCount = 1;
808	            var order = new List<int>();
809	            while (planes.Count > 0)
810	            {
811	                var pool = new List<int>();
812	                for (int i = 0; i < planes.Count; i++)
813	                {
814	                    var planeIdx = TAffine.Planes[planes[i]];
815	                    var n = planeIdx[0];
816	                    var m = planeIdx[1];
817	                    if (n == 0 || mask[m, n - 1] && mask[n, n - 1])
818	                        pool.Add(planes[i]);
819	                }
820	                caseCount *= pool.Count;
821	                var plane = pool[TChromosome.Rnd.Next(pool.Count)];
822	                planes.Remove(plane);
823	                var maskIdx = TAffine.Planes[plane];
824	                mask[maskIdx[1], maskIdx[0]] = true;
825	                order.Add(plane);
826	            }
827	            return order;
828	        }
