830	        bool NonStandard(int[] order)
831	        {
832	            if (order == null) return false;
833	            var mask = new bool[TAffine.N, TAffine.N];
834	            for (int i = 0; i < order.Length; i++)
835	            {
836	                var planeIdx = TAffine.Planes[order[i]];
837	                var n = planeIdx[0];
838	                var m = planeIdx[1];
839	                mask[m, n] = true;
840	                if (n > 0 && (!mask[m, n - 1] || !mask[n, n - 1]))
841	                    return true;
842	            }
843	            return false;
844	        }
