846	        // Moves-to-solve of an orientation under (plane ORDER, mixed-Givens mode): reduce plane by plane in the
847	        // given order[] with a per-plane strategy packed 2 bits per plane in modeMask (base-4): 0=pod-L, 1=nad-L,
848	        // 2=pod-R, 3=nad-R. pod/nad zero the SUB- vs SUPER-diagonal; L/R = row op (left, Rotate, -sin) vs column
849	        // op (right, RotatePost, +sin) - a right op still yields a real cube move (L*M*R = I => M^-1 = R*L).
850	        // Natural order [0..P-1] + modeMask 0 = standard QR baseline. Non-destructive (works on a clone). The
851	        // full P! order space subsumes axis-permutation, so order (not perm) is the diversity axis (diagnostic).
852	        static int RotCountMode(TMatrix M, int[] order, int modeMask)
853	        {
854	            var A = (TMatrix)M.Clone();                        // working copy (non-destructive)
855	            int c = 0;
856	            for (int i = 0; i < order.Length; i++)
857	            {
858	                int p = order[i];
859	                int a1 = TAffine.Planes[p][0], a2 = TAffine.Planes[p][1];
860	                int strat = (modeMask >> (2 * p)) & 3;         // 0=pod-L 1=nad-L 2=pod-R 3=nad-R
861	                float a, b;
862	                switch (strat)
863	                {
864	                    case 0:  a = A[a1, a1]; b =  A[a2, a1]; break;   // pod-L: zero sub-diag [a2,a1] (row op)
865	                    case 1:  a = A[a2, a2]; b = -A[a1, a2]; break;   // nad-L: zero super-diag [a1,a2] (row op)
866	                    case 2:  a = A[a2, a2]; b = -A[a2, a1]; break;   // pod-R: zero sub-diag [a2,a1] (col op)
867	                    default: a = A[a1, a1]; b =  A[a1, a2]; break;   // nad-R: zero super-diag [a1,a2] (col op)
868	                }
869	                float r = (float)Math.Sqrt(a * a + b * b);
870	                if (r < 0.1f) continue;                                            // pivot ~ 0 -> identity rotation
871	                float cos = a / r, sin = b / r;
872	                if (strat < 2) A.Rotate(a1, a2, cos, -sin);        // left: row op, -sin
873	                else           A.RotatePost(a1, a2, cos, sin);     // right: col op, +sin
874	                if (TCubie.GetAngle(cos, sin) != 0) c++;
875	            }
876	            return c;
877	        }
