879	        // mode moves-to-solve of orientation M after applying cube move (plane, angle). Clones the small n x n
880	        // matrix (not the whole cubie) and left-rotates it exactly as Turn rotates a cubie, so the greedy's
881	        // prediction matches the real move; the clone leaves M intact for the sibling candidates.
882	        static int RotCountModeAfter(TMatrix M, int plane, int angle, int[] order, int modeMask)
883	        {
884	            var A = (TMatrix)M.Clone();
885	            var pa = TAffine.Planes[plane];
886	            var rot = TCubie.SetAngle(angle);
887	            A.Rotate(pa[0], pa[1], rot.X, rot.Y);
888	            return RotCountMode(A, order, modeMask);
889	        }
