898	        // A random plane-reduction order (any permutation of the P planes). Drawn per seed so the pool samples
899	        // the strategy x order space - the full generating axis (order subsumes perm, per the diagnostic). An
900	        // order that is invalid for a given (cubie, strategy) just makes the greedy stuck -> null -> redraw.
901	        static int[] RandomOrder()
902	        {
903	            var o = IdentityOrder();
904	            for (int i = o.Length - 1; i > 0; i--)
905	            {
906	                int j = TChromosome.Rnd.Next(i + 1);
907	                (o[i], o[j]) = (o[j], o[i]);
908	            }
909	            return o;
910	        }
