912	        // Greedy solve of the host-designated active cubie under a mixed-Givens mode, via RANDOMIZED
913	        // BACKTRACKING on a lightweight copy of just that cubie (deep Transform, shared geometry). Every
914	        // descent takes a random cube move (plane + 90/180/270) that lowers the mode moves-to-solve by one;
915	        // on a dead end (the metric hits 0 with M != I, or no progress move exists) it backtracks and tries
916	        // another branch instead of giving up. This is the crucial fix over a one-shot descent: a mixed
917	        // mode's solving paths are NARROW, so a single random descent almost always dead-ends and the greedy
918	        // harvested ZERO macro-moves (every non-stuck draw was a minimal-length path). Backtracking finds a
919	        // full length-rc0 path iff one exists, so macro modes (rc0 > minimal) actually yield their longer
920	        // sequences. modeMask == 0 is the standard shortest-solve. Returns null only when the whole monotone
921	        // tree dead-ends (mode genuinely stuck for this cubie) - the caller redraws a fresh mode.
922	        public List<int> GetSolveSeq(int[] order, int modeMask)
923	        {
924	            var c = ActiveCubie.Copy();        // just the cubie - no full-cube clone
925	            var seq = new List<int>();
926	            int rc0 = RotCountMode(c.Transform.M, order, modeMask);
927	            return SolveModeDfs(c, order, modeMask, rc0, seq) ? seq : null;
928	        }
929	
930	        // Depth-first search over the monotone tree (each step drops the mode moves-to-solve by exactly 1),
931	        // random branch order, first solution wins. seq accumulates the realized moves; on backtrack the last
932	        // move is popped. rc == current mode moves-to-solve == depth remaining down to the identity.
933	        bool SolveModeDfs(TCubie c, int[] order, int modeMask, int rc, List<int> seq)
934	        {
935	            if (c.State == 0) return true;                           // reached identity - seq solves the cubie
936	            var cand = new List<int[]>();
937	            for (int plane = 0; plane < TAffine.Planes.Length; plane++)
938	                for (int angle = 1; angle <= 3; angle++)            // quarter-turns: 1/2/3 = 90/180/270
939	                    if (RotCountModeAfter(c.Transform.M, plane, angle, order, modeMask) == rc - 1)
940	                        cand.Add(new[] { plane, angle });
941	            for (int i = cand.Count - 1; i > 0; i--)                // Fisher-Yates: progress moves in random order
942	            {
943	                int j = TChromosome.Rnd.Next(i + 1);
944	                (cand[i], cand[j]) = (cand[j], cand[i]);
945	            }
946	            foreach (var pick in cand)
947	            {
948	                var pa = TAffine.Planes[pick[0]];
949	                var child = c.Copy();
950	                child.Rotate(pa, TCubie.SetAngle(pick[1]));
951	                int axis = TChromosome.Rnd.Next(TAffine.N);          // any axis not in the plane (collateral only)
952	                while (axis == pa[0] || axis == pa[1])
953	                    axis = (axis + 1) % TAffine.N;
954	                seq.Add(new TMove { Plane = pick[0], Angle = pick[1], Axis = axis, Slice = child.GetPos(axis) }.Encode());
955	                if (SolveModeDfs(child, order, modeMask, rc - 1, seq)) return true;
956	                seq.RemoveAt(seq.Count - 1);                         // dead end - undo and try the next branch
957	            }
958	            return false;
959	        }
960	
961	        // Single-descent (NO backtracking) mode solve: at each step take ONE random move that drops the mode
962	        // moves-to-solve by 1; on a dead end (no such move) FAIL (no undo). O(rc) per attempt vs the DFS's
963	        // branching - so cheap even when it fails, and the caller just redraws ("draw until valid"). Narrow
964	        // (macro) modes dead-end often, so the pool ends up mostly minimal - deliberate: the fast SEED path
965	        // trades macro-move material for speed. Mutates its own cubie copy in place (no backtrack -> no copies).
966	        public List<int> GetSolveSeqGreedy(int[] order, int modeMask)
967	        {
968	            var c = ActiveCubie.Copy();
969	            var seq = new List<int>();
970	            int rc = RotCountMode(c.Transform.M, order, modeMask);
971	            while (c.State != 0)
972	            {
973	                int bestPlane = -1, bestAngle = 0, hits = 0;
974	                for (int plane = 0; plane < TAffine.Planes.Length; plane++)
975	                    for (int angle = 1; angle <= 3; angle++)
976	                        if (RotCountModeAfter(c.Transform.M, plane, angle, order, modeMask) == rc - 1
977	                            && TChromosome.Rnd.Next(++hits) == 0)     // reservoir pick: one uniform winner, no list
978	                        { bestPlane = plane; bestAngle = angle; }
979	                if (hits == 0) return null;                           // dead end, no backtrack
980	                var pa = TAffine.Planes[bestPlane];
981	                c.Rotate(pa, TCubie.SetAngle(bestAngle));
982	                int axis = TChromosome.Rnd.Next(TAffine.N);
983	                while (axis == pa[0] || axis == pa[1]) axis = (axis + 1) % TAffine.N;
984	                seq.Add(new TMove { Plane = bestPlane, Angle = bestAngle, Axis = axis, Slice = c.GetPos(axis) }.Encode());
985	                rc--;
986	            }
987	            return seq;
988	        }
