990	        // Legacy standard-metric greedy: same shortest-solve as GetSolveSeq(0), but the moves-to-solve is
991	        // read through the cubie's State getter (which honours the CPU GA's EulerOrder / IsEulerOrderReversed
992	        // toggles), not the explicit mixed-Givens metric. Kept for the CPU path (TRubikGenome.Genesis and the
993	        // warm-up call in ActivateCubie); the GPU seed path uses the mode overload instead.
994	        public List<int> GetSolveSeq()
995	        {
996	            var c = ActiveCubie.Copy();        // just the cubie - no full-cube clone
997	            var seq = new List<int>();
998	            while (c.State != 0)          // State getter refreshes c.RotationCount
999	            {
1000	                int[] pa;
1001	                TVector rot;
1002	                var cand = new List<int[]>();
1003	                for (int plane = 0; plane < TAffine.Planes.Length; plane++)
1004	                    for (int angle = 1; angle <= 3; angle++)   // quarter-turns: 1/2/3 = 90/180/270
1005	                    {
1006	                        var rotCubie = c.Copy();
1007	                        pa = TAffine.Planes[plane];
1008	                        rot = TCubie.SetAngle(angle);
1009	                        rotCubie.Rotate(pa, rot);
1010	                        _ = rotCubie.State;
1011	                        if (rotCubie.RotationCount == c.RotationCount - 1)
1012	                            cand.Add(new[] { plane, angle });
1013	                    }
1014	                var pick = cand[TChromosome.Rnd.Next(cand.Count)];
1015	                pa = TAffine.Planes[pick[0]];
1016	                rot = TCubie.SetAngle(pick[1]);
1017	                c.Rotate(pa, rot);
1018	                int axis = TChromosome.Rnd.Next(TAffine.N);          // any axis not in the plane (collateral only)
1019	                while (axis == pa[0] || axis == pa[1])
1020	                    axis = (axis + 1) % TAffine.N;
1021	                seq.Add(new TMove { Plane = pick[0], Angle = pick[1], Axis = axis, Slice = c.GetPos(axis) }.Encode());
1022	            }
1023	            return seq;
1024	        }
