1026	        // Packs up to numSeeds per-specimen seed sequences into a flat buffer (stride genes each, unused
1027	        // slots = -1 sentinel) for the GPU Init shader. Each draw is a fresh greedy decomposition
1028	        // (GetSolveSeq) under a RANDOMLY chosen mixed-Givens mode, realized with a random axis per move (the
1029	        // axis only picks the collateral layer, not the target's solve, so it adds no decomposition trees).
1030	        // mode 0 is the standard shortest-solve; mixed modes trace longer macro-move paths - the mode pool
1031	        // (2^P) is the dominant diversity source. A stuck mode yields null; we just redraw. Targets
1032	        // populationCount * seedRatioPercent / 100 slots; numSeeds is however many distinct sequences it finds.
1033	        // Canonicalize a move sequence in place: compose consecutive moves in the SAME (axis, plane, slice) as
1034	        // quarter-turns mod 4 (Rz90 Rz90 -> Rz180; Rz90 Rz270 -> removed). Same logic as TRubikGenome.Correct /
1035	        // TGreedyDiversity.CorrectGenes. Run before the seed dedup so two Correct-equal draws fold to one slot
1036	        // instead of being kept as distinct raw strings.
1037	        static void CorrectSeq(List<int> g)
1038	        {
1039	            for (int idx = 0; idx < g.Count; idx++)
1040	            {
1041	                var move = TMove.Decode(g[idx]);
1042	                for (int prev = idx - 1; prev >= 0; prev--)
1043	                {
1044	                    var pm = TMove.Decode(g[prev]);
1045	                    if (pm.Axis != move.Axis || pm.Plane != move.Plane) break;
1046	                    if (pm.Slice == move.Slice)
1047	                    {
1048	                        int angle = (move.Angle + pm.Angle) & 3;         // compose quarter-turns mod 4
1049	                        if (angle > 0) { pm.Angle = angle; g[prev] = pm.Encode(); }
1050	                        else { g.RemoveAt(prev); idx--; }
1051	                        g.RemoveAt(idx); idx--;
1052	                        break;
1053	                    }
1054	                }
1055	            }
1056	        }
