1058	        public static bool Diagnostic;       // set by Gpu.SeedStats: enables the census + report in BuildSeedMoves
1059	        public string LastSeedReport = "";   // filled by BuildSeedMoves (only when Diagnostic); shown by Seed Pool Stats
1060	
1061	        public int[] BuildSeedMoves(int populationCount, int stride, int seedRatioPercent, bool mixedModes, bool fast, out uint numSeeds)
1062	        {
1063	            int target = populationCount * seedRatioPercent / 100;
1064	            int modeSpace = mixedModes ? 1 << (2 * TAffine.Planes.Length) : 1;   // 4^P strategies; SEED_MODE 0 -> mode 0 (baseline)
1065	            var slots = new List<int[]>();
1066	            var seen = new HashSet<string>();
1067	            // The distinct-manoeuvre pool across modes is far richer than the single-tree shortest-solve pool,
1068	            // but still finite. Stop once draws stop producing anything new (pool saturated) instead of
1069	            // spinning a fixed guard; the stall budget scales with what we found so far so bigger pools get
1070	            // patience. Both a stuck mode (null) and a duplicate count as a no-progress draw.
1071	            int stall = 0;
1072	            int draws = 0, stuck = 0, dupes = 0;                     // telemetry: why the pool ends up the size it is
1073	            var lenHist = new SortedDictionary<int, int>();          // accepted-seed length distribution
1074	            var modeContrib = new HashSet<int>();                    // distinct modes that landed >=1 accepted seed
1075	            var ident = IdentityOrder();
1076	            // Safe LOWER bound on moves-to-solve: each move is a Givens in one plane (2 axes), so it can fix at
1077	            // most 2 axes -> solving d non-fixed axes needs >= ceil(d/2) moves. (Standard QR is only an UPPER
1078	            // bound - e.g. diag(-1,1,-1) is 1 move via plane (0,2) but standard QR at natural order counts 2 -
1079	            // so using it here would wrongly skip valid short solves. This bound never over-skips.)
1080	            int min = (ActiveCubie.ActiveAxisCount() + 1) / 2;
1081	            // A no-progress draw (stuck mode or duplicate). We call the pool saturated once a run of them
1082	            // outlasts a budget that grows with the pool - a bigger pool earns more patience. One method,
1083	            // so the three no-progress branches below read identically instead of repeating the expression.
1084	            bool Saturated() => ++stall > 32 + 8 * slots.Count;
1085	            if (fast)
1086	            {
1087	                // FAST path: one single random descent per draw (GetSolveSeqGreedy, NO backtracking), thrown in
1088	                // "as they come" with NO dedup. A descent that dead-ends on a narrow mode returns null and is just
1089	                // redrawn ("draw until valid") - cheap because each attempt is O(rc), not the DFS's branching. Cap
1090	                // the draws so a cubie whose modes all dead-end on a single descent can't spin forever; whatever we
1091	                // gathered is topped up to target by repetition below. Duplicates are FINE here (more of the same
1092	                // easy manoeuvre is legitimate seed material), so no seen-set, no CorrectSeq, no saturation budget.
1093	                int maxDraws = 32 * target + 64;
1094	                for (int draw = 0; slots.Count < target && draw < maxDraws; draw++)
1095	                {
1096	                    int mode = mixedModes ? TChromosome.Rnd.Next(modeSpace) : 0;
1097	                    var order = mixedModes ? RandomOrder() : ident;
1098	                    var seq = GetSolveSeqGreedy(order, mode);        // single descent; null on any dead end
1099	                    if (seq == null) { draws++; stuck++; continue; }  // narrow mode dead-ended -> redraw
1100	                    if (seq.Count == 0) break;                        // cubie already solved -> no seeds
1101	                    slots.Add(seq.ToArray());
1102	                    lenHist.TryGetValue(seq.Count, out int hc); lenHist[seq.Count] = hc + 1;
1103	                    modeContrib.Add(mode);
1104	                }
1105	            }
1106	            else
1107	            while (slots.Count < target)
1108	            {
1109	                int mode = TChromosome.Rnd.Next(modeSpace);
1110	                var order = mixedModes ? RandomOrder() : ident;      // random plane-reduction order (baseline: natural)
1111	                draws++;
1112	                if (RotCountMode(ActiveCubie.Transform.M, order, mode) < min)   // undercounting -> provably stuck, skip the DFS
1113	                { stuck++; if (Saturated()) break; continue; }
1114	                var seq = GetSolveSeq(order, mode);                  // greedy under (random order, random mode)
1115	                if (seq == null) { stuck++; if (Saturated()) break; continue; }  // rc0>=min but still stuck
1116	                if (seq.Count == 0) break;                            // cubie already solved -> no seeds
1117	                CorrectSeq(seq);                                      // canonicalize before dedup: fold Correct-equal draws
1118	                var moves = seq.ToArray();
1119	                if (seen.Add(string.Join(",", moves)))
1120	                {
1121	                    slots.Add(moves); stall = 0;
1122	                    lenHist.TryGetValue(moves.Length, out int hc); lenHist[moves.Length] = hc + 1;
1123	                    modeContrib.Add(mode);
1124	                }
1125	                else
1126	                {
1127	                    dupes++;
1128	                    if (Saturated()) break;                           // long run with no new manoeuvre: exhausted
1129	                }
1130	            }
1131	
1132	            // Census + report are DIAGNOSTIC-only (Seed Pool Stats): the census alone is modeSpace (up to 4^P =
1133	            // 4096) extra RotCountMode calls per cubie - pure waste in production. Skip unless Diagnostic is set.
1134	            if (Diagnostic)
1135	            {
1136	                // mode census: rc0 (mode moves-to-solve) of THIS cubie under each mode (at natural order). Path
1137	                // length == rc0, so this is the cubie's macro-move potential. All rc0 == minimal => degenerate
1138	                // (shallow) cubie; a spread => deep orientation that mixed modes inflate into macro-moves.
1139	                var rc0Hist = new SortedDictionary<int, int>();
1140	                for (int mode = 0; mode < modeSpace; mode++)
1141	                {
1142	                    int r = RotCountMode(ActiveCubie.Transform.M, ident, mode);
1143	                    rc0Hist.TryGetValue(r, out int hc); rc0Hist[r] = hc + 1;
1144	                }
1145	
1146	                var rep = new System.Text.StringBuilder();
1147	                rep.AppendLine($"[BuildSeedMoves]  N={TAffine.N}  SEED_MODE={(mixedModes ? 1 : 0)}  order={(mixedModes ? "random" : "natural")}  stride={stride}  target={target}  ({seedRatioPercent}% of population)");
1148	                rep.AppendLine($"distinct seeds = {slots.Count}     draws={draws}  stuck={stuck}  dupes={dupes}");
1149	                if (slots.Count > 0 && slots.Count < target)
1150	                    rep.AppendLine($"pool < target -> {target} slots filled by repeating the {slots.Count} distinct seeds");
1151	                rep.AppendLine($"distinct modes contributing = {modeContrib.Count} / {modeSpace}");
1152	                rep.Append("mode rc0 census (moves:modes):");
1153	                foreach (var kv in rc0Hist) rep.Append($"  {kv.Key}:{kv.Value}");
1154	                rep.AppendLine();
1155	                rep.Append("accepted length histogram (moves:count):");
1156	                foreach (var kv in lenHist) rep.Append($"  {kv.Key}:{kv.Value}");
1157	                LastSeedReport = rep.ToString();
1158	                System.Diagnostics.Debug.WriteLine(LastSeedReport);
1159	            }
1160	
1161	            // Seed the FULL target, not just as many specimens as the pool has distinct manoeuvres. A shallow
1162	            // cubie with few decompositions no longer leaves the population under-seeded: every distinct seed is
1163	            // placed once (slots 0..pool), then the remaining slots are topped up by sampling the pool with
1164	            // repetition. numSeeds = target so Init pre-seeds exactly that many specimens.
1165	            if (slots.Count == 0) { numSeeds = 0; return new int[1]; }   // nothing to seed (solved / stuck); never a zero-size SSBO
1166	            numSeeds = (uint)target;
1167	            var buf = new int[target * stride];
1168	            for (int s = 0; s < target; s++)
1169	            {
1170	                int[] seed = s < slots.Count ? slots[s] : slots[TChromosome.Rnd.Next(slots.Count)];
