643	            if (MoveTimer.Enabled) return;                 // don't fight an interactive solve in progress
644	            var title = Text;
645	            var results = new int[BATCH_RUNS];
646	            var hung = new bool[BATCH_RUNS];
647	            var times = new double[BATCH_RUNS];             // per-run GA compute time (ms) -- the cost the gen count hides
648	            List<string> worstTraj = null; int worstResult = -1, worstRun = -1;
649	            for (int r = 0; r < BATCH_RUNS; r++)
650	            {
651	                Text = $"BATCH {r + 1}/{BATCH_RUNS} ...";
652	                Application.DoEvents();                     // let the title repaint; no input is processed meaningfully
653	                results[r] = SolveOnceHeadless(out hung[r], out var traj, out times[r]);
654	                if (results[r] > worstResult) { worstResult = results[r]; worstTraj = traj; worstRun = r; }   // keep only the worst
655	            }
656	            Text = title;
657	            tglView1.Invalidate();
658	
659	            // Stats over ALL runs (hung ones counted at the cap -- conservative, and flagged).
660	            var sorted = (int[])results.Clone();
661	            Array.Sort(sorted);
662	            double mean = results.Average();
663	            double var = results.Select(v => (v - mean) * (v - mean)).Average();
664	            double median = BATCH_RUNS % 2 == 1
665	                ? sorted[BATCH_RUNS / 2]
666	                : (sorted[BATCH_RUNS / 2 - 1] + sorted[BATCH_RUNS / 2]) / 2.0;
667	            int hangCount = hung.Count(h => h);
668	
669	            var sb = new StringBuilder();
