675	                          $"Floor={Gpu.Floor}  Population={TGA<TRubikGenome>.PopulationCount}  cap={BATCH_CAP}" +
676	                          (measure != null ? $"  MEASURE={measure}" : "") +
677	                          (pair != null ? $"  PAIR={pair}" : "") +
678	                          (ssign != null ? $"  variant={(ssign.Contains("-") ? "-S" : ssign == "0" ? "0" : "+S")}" : ""));
679	            sb.AppendLine("runs: " + string.Join(", ",
680	                results.Select((v, i) => hung[i] ? v + "(HANG)" : v.ToString())));
681	            sb.AppendLine($"min {sorted[0]}   median {median}   tail {sorted[BATCH_RUNS - 1]}   " +
682	                          $"mean {mean:F0}   std {Math.Sqrt(var):F0}   var {var:F0}" +
683	                          (hangCount > 0 ? $"   HANGS {hangCount}/{BATCH_RUNS}" : ""));
684	            double totMs = times.Sum(), totGen = results.Sum();   // ms/1k-gen = per-generation cost -> the GPU-efficiency knob (coherence-on costs more)
685	            sb.AppendLine($"time ms: total {totMs:F0}   mean {times.Average():F0}   tail {times.Max():F0}   " +
686	                          $"ms/1k-gen {(totGen > 0 ? 1000.0 * totMs / totGen : 0):F1}");
