66	        public TRubikCube()
67	        {
68	            var size = 1;
69	            var scale = new TVector(TAffine.N);
70	            TCubie.Scaling = new TVector(TAffine.N);
71	            var dimSizes = new int[TAffine.N];
72	            var s = 0.9f / (TAffine.N - 1);// / (TAffine.N - 2);
73	            for (int dim = 0; dim < TAffine.N; dim++)
74	            {
75	                size *= Size;
76	                dimSizes[dim] = Size;
77	                scale[dim] = 1f / Size;
78	                TCubie.Scaling[dim] = s;
79	            }
80	            Cubies = new TCubie[size];
81	            TCubie.SizeMatrix = new TMatrix(size, 1);
82	            TCubie.SizeMatrix.DimSizes = dimSizes;
83	            TCubie.MaxScore = 1 << 2 * TAffine.Planes.Length;
84	            //TCubie.Cube = CreateHyperCube();
85	            //TMove.UpdateSizeMatrix();
86	            C = (Size - 1) / 2f;
87	            Scale(scale);
88	            for (int i = 0; i < Cubies.Length; i++)
89	            {
90	                var cubie = new TCubie();
91	                cubie.Transform = TAffine.CreateScale(TCubie.Scaling);
92	                cubie.GivensOrder = TVector.Uniform(TAffine.N);
93	                cubie.Index = i;                 // setter stamps the sparse orbit-based ClusterIndex
94	                cubie.StartIndex = i;
