881	        public int[] BuildSeedMoves(int populationCount, int stride, int seedRatioPercent, bool mixedModes, bool fast, out uint numSeeds)
882	        {
883	            int target = populationCount * seedRatioPercent / 100;
884	            int modeSpace = mixedModes ? 1 << (2 * TAffine.Planes.Length) : 1;   // 4^P strategies; SEED_MODE 0 -> mode 0 (baseline)
885	            var slots = new List<int[]>();
886	            var seen = new HashSet<string>();
887	            // The distinct-manoeuvre pool across modes is far richer than the single-tree shortest-solve pool,
888	            // but still finite. Stop once draws stop producing anything new (pool saturated) instead of
889	            // spinning a fixed guard; the stall budget scales with what we found so far so bigger pools get
890	            // patience. Both a stuck mode (null) and a duplicate count as a no-progress draw.
891	            int stall = 0;
892	            int draws = 0, stuck = 0, dupes = 0;                     // telemetry: why the pool ends up the size it is
893	            var lenHist = new SortedDictionary<int, int>();          // accepted-seed length distribution
894	            var modeContrib = new HashSet<int>();                    // distinct modes that landed >=1 accepted seed
895	            var ident = IdentityOrder();
896	            // Safe LOWER bound on moves-to-solve: each move is a Givens in one plane (2 axes), so it can fix at
897	            // most 2 axes -> solving d non-fixed axes needs >= ceil(d/2) moves. (Standard QR is only an UPPER
898	            // bound - e.g. diag(-1,1,-1) is 1 move via plane (0,2) but standard QR at natural order counts 2 -
899	            // so using it here would wrongly skip valid short solves. This bound never over-skips.)
900	            int min = (ActiveCubie.ActiveAxisCount() + 1) / 2;
901	            // A no-progress draw (stuck mode or duplicate). We call the pool saturated once a run of them
902	            // outlasts a budget that grows with the pool - a bigger pool earns more patience. One method,
903	            // so the three no-progress branches below read identically instead of repeating the expression.
904	            bool Saturated() => ++stall > 32 + 8 * slots.Count;
905	            if (fast)
906	            {
907	                // FAST path: one single random descent per draw (GetSolveSeqGreedy, NO backtracking), thrown in
908	                // "as they come" with NO dedup. A descent that dead-ends on a narrow mode returns null and is just
909	                // redrawn ("draw until valid") - cheap because each attempt is O(rc), not the DFS's branching. Cap
910	                // the draws so a cubie whose modes all dead-end on a single descent can't spin forever; whatever we
911	                // gathered is topped up to target by repetition below. Duplicates are FINE here (more of the same
912	                // easy manoeuvre is legitimate seed material), so no seen-set, no CorrectSeq, no saturation budget.
913	                int maxDraws = 32 * target + 64;
914	                for (int draw = 0; slots.Count < target && draw < maxDraws; draw++)
915	                {
916	                    int mode = mixedModes ? TChromosome.Rnd.Next(modeSpace) : 0;
917	                    var order = mixedModes ? RandomOrder() : ident;
918	                    var seq = GetSolveSeqGreedy(order, mode);        // single descent; null on any dead end
919	                    if (seq == null) { draws++; stuck++; continue; }  // narrow mode dead-ended -> redraw
920	                    if (seq.Count == 0) break;                        // cubie already solved -> no seeds
921	                    slots.Add(seq.ToArray());
