1	using GA;
2	using System.Collections.Generic;
3	using System.Diagnostics;
4	
5	namespace RubikCube
6	{
7	    // The SEARCH over a cube. Split out of TRubikCube so the cube stays pure geometry (state + Turn +
8	    // clusters) that the window holds for drawing, while the solver owns the GA decision loop and its
9	    // per-solve state (accept baseline, stall, running best, generation count, compute time). Created
10	    // FRESH right before a solve (construction IS the reset -- fields default to zero, ComputeTime is
11	    // fresh); binds one cube via Cube. The GPU driver reads solver state through ExecuteGA(this), so
12	    // Score/IterationsCount live here, not on the cube.
13	    public class TRubikSolver
14	    {
15	        public readonly TRubikCube Cube;
16	
17	        // Coherence LATCH THRESHOLD + endgame NORMALIZER base (uploaded to GPU uniform 7). Shared config, never
18	        // mutated (a search knob, not GPU state): the latch flips Coherent 0->1 when the residual reaches it, and
19	        // the coherence factor normalizes by Floor*N. Read by name (TRubikSolver.Floor) from Gpu and the batch report.
20	        public static uint Floor = 4;
21	
22	        public float Score;            // fitness of the currently ACCEPTED config -- the accept-test baseline
23	        public uint Coherent;          // coherence LATCH (per-solve): 0 = count-peel descent, 1 = endgame coherence. Passed into every GPU call so the GA and ScoreCube use the same value. Reset to 0 per cluster in NextCluster.
24	        uint ScoreLadder;              // ladder value of the accepted config -- the coherence accept baseline (GPU-computed)
25	        public int Scrambled;          // active-cluster residual count (read by the UI)
26	        public TRubikGenome Best;      // last accepted specimen (the displayed/applied state)
27	        public int IterationsCount;    // total GA generations across this solve (accumulated by ExecuteGA)
28	        int Stall;                     // consecutive non-improving GA runs -- the sideways/latch timer
29	
30	        // Accumulated GA COMPUTE time (GPU work + orchestration) across all GetNextMoves steps of this
31	        // solve -- the piece the generation count hides: coherence-on steps cost far more than count-peel
32	        // steps. Read by the form for display and by the batch for per-run timing.
33	        public readonly Stopwatch ComputeTime = new Stopwatch();
34	
35	        public TRubikSolver(TRubikCube cube)
36	        {
37	            Cube = cube;
38	            Cube.ActiveCubie = null;   // start from cluster 1 (the only state the old TRubikCube.Reset set)
39	        }
40	
41	        // ONE GA decision step -- Runs in BOTH phases
42	        // (the count-peel descent AND the post-floor coherence climb). It:
43	        //   1. re-selects the target cubie -- UNSOLVED one of the active cluster -- which is what lets
44	        //      successive GA runs during a stall attack the SAME configuration from different cubies;
45	        //   2. advances to the next cluster when the current one is solved (descent phase, base floor);
46	        //   3. runs one GA and applies the STALL accept test (accept strictly-better always, equal only after
47	        //      StallLimit consecutive non-improving runs -- a gated sideways step off a plateau).
48	        // Returns the accepted moves (empty if none, or if the whole cube is solved -> Best == null).
49	        public List<TMove> GetNextMoves()
50	        {
51	            ComputeTime.Start();                       // accumulate GA compute time (paired Stop before EVERY return)
52	            var moves = new List<TMove>();
53	            if (Score == 0)                            // current cluster solved -> advance
54	                NextCluster();
55	            if (Cube.ActiveCubie == null) // whole cube solved
56	            {
57	                Best = null;
58	                ComputeTime.Stop();
59	                return moves;
60	            }
61	            Scrambled = 0;
62	            foreach (var c in Cube.ActiveCluster) if (c.State != 0) Scrambled++;
63	            // COHERENCE LATCH (no walk). Two phases: during the DESCENT coherence is OFF, so the evaluator is the
64	            // bare count and the peel drives the residual down fast; once the active cluster's residual reaches the
65	            // floor (base 4), latch coherence ON for the ENDGAME and leave it on for the rest of the cluster. The
66	            // floor is now ONLY this latch threshold -- it never walks. Count-cancellation lives inside the metric
67	            // (the /scrambled in the coherence factor), so once latched the fitness is the bare coherence factor
68	            // for the whole endgame (0 < scrambled <= G) and the yardstick never jumps. The latch itself DOES
69	            // switch metrics (count -> factor), so Score (the accept-test reference) is re-measured once, at the
70	            // flip. Reset to descent (coherence OFF, floor 4) per cluster in NextCluster. Called after the moves
71	            // are applied, when the cube IS the state just reached.
72	            if (Coherent == 0 && Scrambled <= (int)Floor) // && Stall > (int)Floor)
73	            {
74	                Coherent = 1;
75	                Score = Gpu.ScoreCube(Cube, Coherent);
76	                ScoreLadder = Gpu.LastScoreLadder;
77	                Stall = 0;
78	            }
79	            // advance target: DETERMINISTIC round-robin --  // the next UNSOLVED cubie of the cluster after the
80	            var cluster = Cube.ActiveCluster;      // current one (wrapping). Cluster order is stable
81	            int cur = cluster.IndexOf(Cube.ActiveCubie);// (Cubies array order), so successive steps cycle
82	            for (int step = 1; step <= cluster.Count; step++)// through all cubies once per pass -- no coupon-
83	            {                                                // collector waste of the old random pick, and it
84	                var cand = cluster[(cur + step) % cluster.Count];  // pairs exactly with StallLimit = #unsolved.
85	                if (cand.State != 0) { Cube.ActiveCubie = cand; break; }
86	            }
87	            TRubikGenome.RubikCube = Cube;
88	            var candidate = Gpu.ExecuteGA(this, out int gens);   // fresh GA result; Best (the displayed/accepted state) advances ONLY on accept
89	            IterationsCount += gens;               // accumulate here (ExecuteGA reports gens instead of writing us)
