595	        // Packs up to numSeeds per-specimen seed sequences into a flat buffer (stride genes each, unused
596	        // slots = -1 sentinel) for the GPU Init shader. Each draw is a fresh greedy decomposition
597	        // (GetSolveSeq) under a RANDOMLY chosen mixed-Givens mode, realized with a random axis per move (the
598	        // axis only picks the collateral layer, not the target's solve, so it adds no decomposition trees).
599	        // mode 0 is the standard shortest-solve; mixed modes trace longer macro-move paths - the mode pool
600	        // (2^P) is the dominant diversity source. A stuck mode yields null; we just redraw. Targets
601	        // populationCount * seedRatioPercent / 100 slots; numSeeds is however many distinct sequences it finds.
602	        // Canonicalize a move sequence in place: compose consecutive moves in the SAME (axis, plane, slice) as
603	        // quarter-turns mod 4 (Rz90 Rz90 -> Rz180; Rz90 Rz270 -> removed). Same logic as TRubikGenome.Correct /
604	        // TGreedyDiversity.CorrectGenes. Run before the seed dedup so two Correct-equal draws fold to one slot
605	        // instead of being kept as distinct raw strings.
606	        static void CorrectSeq(List<int> g)
607	        {
608	            for (int idx = 0; idx < g.Count; idx++)
609	            {
610	                var move = TMove.Decode(g[idx]);
611	                for (int prev = idx - 1; prev >= 0; prev--)
612	                {
613	                    var pm = TMove.Decode(g[prev]);
614	                    if (pm.Axis != move.Axis || pm.Plane != move.Plane) break;
615	                    if (pm.Slice == move.Slice)
616	                    {
617	                        int angle = (move.Angle + pm.Angle) & 3;         // compose quarter-turns mod 4
618	                        if (angle > 0) { pm.Angle = angle; g[prev] = pm.Encode(); }
619	                        else { g.RemoveAt(prev); idx--; }
620	                        g.RemoveAt(idx); idx--;
621	                        break;
622	                    }
623	                }
624	            }
625	        }
