630	        public int[] BuildSeedMoves(int populationCount, int stride, int seedRatioPercent, bool mixedModes, bool fast, out uint numSeeds)
631	        {
632	            int target = populationCount * seedRatioPercent / 100;
633	            int modeSpace = mixedModes ? 1 << (2 * TAffine.Planes.Length) : 1;   // 4^P strategies; SEED_MODE 0 -> mode 0 (baseline)
634	            var slots = new List<int[]>();
635	            var seen = new HashSet<string>();
636	            // The distinct-manoeuvre pool across modes is far richer than the single-tree shortest-solve pool,
637	            // but still finite. Stop once draws stop producing anything new (pool saturated) instead of
638	            // spinning a fixed guard; the stall budget scales with what we found so far so bigger pools get
639	            // patience. Both a stuck mode (null) and a duplicate count as a no-progress draw.
640	            int stall = 0;
641	            int draws = 0, stuck = 0, dupes = 0;                     // telemetry: why the pool ends up the size it is
642	            var lenHist = new SortedDictionary<int, int>();          // accepted-seed length distribution
643	            var modeContrib = new HashSet<int>();                    // distinct modes that landed >=1 accepted seed
644	            var ident = IdentityOrder();
645	            // Safe LOWER bound on moves-to-solve: each move is a Givens in one plane (2 axes), so it can fix at
646	            // most 2 axes -> solving d non-fixed axes needs >= ceil(d/2) moves. (Standard QR is only an UPPER
647	            // bound - e.g. diag(-1,1,-1) is 1 move via plane (0,2) but standard QR at natural order counts 2 -
648	            // so using it here would wrongly skip valid short solves. This bound never over-skips.)
649	            int min = (ActiveCubie.ActiveAxisCount() + 1) / 2;
650	            // A no-progress draw (stuck mode or duplicate). We call the pool saturated once a run of them
651	            // outlasts a budget that grows with the pool - a bigger pool earns more patience. One method,
652	            // so the three no-progress branches below read identically instead of repeating the expression.
653	            bool Saturated() => ++stall > 32 + 8 * slots.Count;
654	            if (fast)
655	            {
656	                // FAST path: one single random descent per draw (GetSolveSeqGreedy, NO backtracking), thrown in
657	                // "as they come" with NO dedup. A descent that dead-ends on a narrow mode returns null and is just
658	                // redrawn ("draw until valid") - cheap because each attempt is O(rc), not the DFS's branching. Cap
659	                // the draws so a cubie whose modes all dead-end on a single descent can't spin forever; whatever we
660	                // gathered is topped up to target by repetition below. Duplicates are FINE here (more of the same
661	                // easy manoeuvre is legitimate seed material), so no seen-set, no CorrectSeq, no saturation budget.
662	                int maxDraws = 32 * target + 64;
663	                for (int draw = 0; slots.Count < target && draw < maxDraws; draw++)
664	                {
665	                    int mode = mixedModes ? TChromosome.Rnd.Next(modeSpace) : 0;
666	                    var order = mixedModes ? RandomOrder() : ident;
667	                    var seq = GetSolveSeqGreedy(order, mode);        // single descent; null on any dead end
668	                    if (seq == null) { draws++; stuck++; continue; }  // narrow mode dead-ended -> redraw
669	                    if (seq.Count == 0) break;                        // cubie already solved -> no seeds
670	                    slots.Add(seq.ToArray());
671	                    lenHist.TryGetValue(seq.Count, out int hc); lenHist[seq.Count] = hc + 1;
672	                    modeContrib.Add(mode);
673	                }
674	            }
675	            else
676	            while (slots.Count < target)
677	            {
678	                int mode = TChromosome.Rnd.Next(modeSpace);
679	                var order = mixedModes ? RandomOrder() : ident;      // random plane-reduction order (baseline: natural)
680	                draws++;
681	                if (RotCountMode(ActiveCubie.Transform.M, order, mode) < min)   // undercounting -> provably stuck, skip the DFS
682	                { stuck++; if (Saturated()) break; continue; }
683	                var seq = GetSolveSeq(order, mode);                  // greedy under (random order, random mode)
684	                if (seq == null) { stuck++; if (Saturated()) break; continue; }  // rc0>=min but still stuck
685	                if (seq.Count == 0) break;                            // cubie already solved -> no seeds
686	                CorrectSeq(seq);                                      // canonicalize before dedup: fold Correct-equal draws
687	                var moves = seq.ToArray();
688	                if (seen.Add(string.Join(",", moves)))
689	                {
690	                    slots.Add(moves); stall = 0;
691	                    lenHist.TryGetValue(moves.Length, out int hc); lenHist[moves.Length] = hc + 1;
692	                    modeContrib.Add(mode);
693	                }
694	                else
695	                {
696	                    dupes++;
697	                    if (Saturated()) break;                           // long run with no new manoeuvre: exhausted
698	                }
699	            }
700	
701	            // Census + report are DIAGNOSTIC-only (Seed Pool Stats): the census alone is modeSpace (up to 4^P =
702	            // 4096) extra RotCountMode calls per cubie - pure waste in production. Skip unless Diagnostic is set.
703	            if (Diagnostic)
704	            {
705	                // mode census: rc0 (mode moves-to-solve) of THIS cubie under each mode (at natural order). Path
706	                // length == rc0, so this is the cubie's macro-move potential. All rc0 == minimal => degenerate
707	                // (shallow) cubie; a spread => deep orientation that mixed modes inflate into macro-moves.
708	                var rc0Hist = new SortedDictionary<int, int>();
709	                for (int mode = 0; mode < modeSpace; mode++)
710	                {
711	                    int r = RotCountMode(ActiveCubie.Transform.M, ident, mode);
712	                    rc0Hist.TryGetValue(r, out int hc); rc0Hist[r] = hc + 1;
713	                }
714	
715	                var rep = new System.Text.StringBuilder();
716	                rep.AppendLine($"[BuildSeedMoves]  N={TAffine.N}  SEED_MODE={(mixedModes ? 1 : 0)}  order={(mixedModes ? "random" : "natural")}  stride={stride}  target={target}  ({seedRatioPercent}% of population)");
717	                rep.AppendLine($"distinct seeds = {slots.Count}     draws={draws}  stuck={stuck}  dupes={dupes}");
718	                if (slots.Count > 0 && slots.Count < target)
719	                    rep.AppendLine($"pool < target -> {target} slots filled by repeating the {slots.Count} distinct seeds");
720	                rep.AppendLine($"distinct modes contributing = {modeContrib.Count} / {modeSpace}");
721	                rep.Append("mode rc0 census (moves:modes):");
722	                foreach (var kv in rc0Hist) rep.Append($"  {kv.Key}:{kv.Value}");
723	                rep.AppendLine();
724	                rep.Append("accepted length histogram (moves:count):");
725	                foreach (var kv in lenHist) rep.Append($"  {kv.Key}:{kv.Value}");
726	                LastSeedReport = rep.ToString();
727	                System.Diagnostics.Debug.WriteLine(LastSeedReport);
728	            }
729	
730	            // Seed the FULL target, not just as many specimens as the pool has distinct manoeuvres. A shallow
731	            // cubie with few decompositions no longer leaves the population under-seeded: every distinct seed is
732	            // placed once (slots 0..pool), then the remaining slots are topped up by sampling the pool with
733	            // repetition. numSeeds = target so Init pre-seeds exactly that many specimens.
734	            if (slots.Count == 0) { numSeeds = 0; return new int[1]; }   // nothing to seed (solved / stuck); never a zero-size SSBO
735	            numSeeds = (uint)target;
736	            var buf = new int[target * stride];
737	            for (int s = 0; s < target; s++)
738	            {
739	                int[] seed = s < slots.Count ? slots[s] : slots[TChromosome.Rnd.Next(slots.Count)];
740	                int k = 0;
741	                for (; k < seed.Length && k < stride; k++) buf[s * stride + k] = seed[k];
742	                for (; k < stride; k++) buf[s * stride + k] = -1;
743	            }
744	            return buf;
745	        }
746	
747	    }
748	}
