8	{
9	    // One orbit of cubies (a "cluster") in a SPECIFIC cube instance. Membership is geometry (the orbit is
10	    // fixed for a given N/SIZE), but Cubies are THIS cube's TCubie objects -- meaningful in the debugger
11	    // (StartIndex/State/position), not opaque indices. Built per cube: the scratch ctor groups by orbit,
12	    // the copy ctor mirrors by StartIndex. Size == Cubies.Count (kept as a field for the MaxClusterSize scan).
13	    public class TCluster
14	    {
15	        public int Size;
16	        public static int MaxClusterSize = 12;
17	        public List<TCubie> Cubies = new List<TCubie>();
18	    }
19	}

