11	using TGL;
12	
13	namespace RubikCube
14	{
15	    public class TRubikCube : TShape
16	    {
17	        public static int Size = 3;
18	        public static float C;
19	        public TCubie[] Cubies;
20	        public static List<int> EulerOrder;
21	        public static bool IsEulerOrderReversed;
22	        // Cluster STRUCTURE (orbits) of THIS cube -- pure geometry. Per-instance now (each holds its own cubie
23	        // refs), built by the two ctors. The SEARCH target (which cluster/cubie is active, what's solved) lives
24	        // on TRubikSolver, not here -- a cube has no "active cubie".
25	        public List<TCluster> Clusters = new List<TCluster>();
