66	        {
67	            var size = 1;
68	            var scale = new TVector(TAffine.N);
69	            TCubie.Scaling = new TVector(TAffine.N);
70	            var dimSizes = new int[TAffine.N];
71	            var s = 0.9f / (TAffine.N - 1);// / (TAffine.N - 2);
72	            for (int dim = 0; dim < TAffine.N; dim++)
73	            {
74	                size *= Size;
75	                dimSizes[dim] = Size;
76	                scale[dim] = 1f / Size;
77	                TCubie.Scaling[dim] = s;
78	            }
79	            Cubies = new TCubie[size];
80	            TCubie.SizeMatrix = new TMatrix(size, 1);
81	            TCubie.SizeMatrix.DimSizes = dimSizes;
82	            TCubie.MaxScore = 1 << 2 * TAffine.Planes.Length;
83	            //TCubie.Cube = CreateHyperCube();
84	            //TMove.UpdateSizeMatrix();
85	            C = (Size - 1) / 2f;
86	            Scale(scale);
87	            for (int i = 0; i < Cubies.Length; i++)
88	            {
89	                var cubie = new TCubie();
90	                cubie.Transform = TAffine.CreateScale(TCubie.Scaling);
91	                cubie.GivensOrder = TVector.Uniform(TAffine.N);
92	                cubie.Index = i;                 // setter stamps the sparse orbit-based ClusterIndex
93	                cubie.StartIndex = i;
94	                cubie.Parent = this;
95	                Cubies[i] = cubie;
96	            }
97	            RenumberClusters();
98	        }
99	
100	        // The Index setter stamps each cubie with a sparse ORBIT index (linear index of its sorted |coords|
101	        // from the centre - a distance class), so values are non-contiguous and run into the thousands. Remap
102	        // them to a dense, sequential cluster rank 1,2,3,... in ascending orbit order: now ClusterIndex reads
103	        // as a real "k-th cluster" and ClustersCount is the number of clusters. NextCluster (min ClusterIndex)
104	        // and ActiveCluster (equality) depend only on order and equality - both preserved by this monotonic
105	        // remap - so the solve order is unchanged.
106	        private void RenumberClusters()
107	        {
108	            Clusters.Clear();
109	            var byOrbit = new List<TCubie>(Cubies);
110	            byOrbit.Sort((a, b) => a.ClusterIndex.CompareTo(b.ClusterIndex));
111	            int rank = 0, prevOrbit = int.MinValue;
112	            TCluster cluster = null;
113	            foreach (var cubie in byOrbit)
114	            {
115	                int orbit = cubie.ClusterIndex;                  // still the orbit index (not yet remapped)
116	                if (orbit != prevOrbit)
117	                {
118	                    rank++;
119	                    cluster = new TCluster();
120	                    Clusters.Add(cluster);
121	                    prevOrbit = orbit;
122	                }
123	                cubie.ClusterIndex = rank;
124	                cluster.Cubies.Add(cubie);   // this cube's cubie objects; Clusters[k-1] is the rank-k cluster
125	                cluster.Size++;
126	            }
127	            //ClustersCount = rank;
128	            MaxClusterSize = Clusters.Max(c => c.Size);
129	        }
